<script setup>
import{onMounted,onUnmounted,ref}from'vue'
import {Drawer as ADrawer} from 'ant-design-vue'
import {confirmAction} from '../ui'
import{api,can}from'../api'
const state=ref(null),tasks=ref([]),total=ref(0),page=ref(1),status=ref(''),kind=ref(''),error=ref(''),success=ref(''),busy=ref(false),auto=ref(true),detail=ref(null),docs=ref([]),documentId=ref('')
const states={queued:'排队',running:'执行中',completed:'完成',needs_review:'待评审',failed:'失败',interrupted:'中断',cancelled:'取消'},kinds={report:'报告生成',report_section:'报告单节重生成',template_design:'模板设计',reindex:'重新切分',ingest:'文档处理流水线'}
let timer=null,loading=false
const bytes=value=>value==null?'—':value>=1073741824?`${(value/1073741824).toFixed(2)} GB`:value>=1048576?`${(value/1048576).toFixed(2)} MB`:`${(value/1024).toFixed(1)} KB`
async function load(){if(loading)return;loading=true;try{const query=new URLSearchParams({page:page.value,page_size:20});if(status.value)query.set('status',status.value);if(kind.value)query.set('kind',kind.value);const [runtime,data]=await Promise.all([api('/api/operations'),api('/api/tasks?'+query)]);state.value=runtime;tasks.value=data.items;total.value=data.total;if(detail.value)detail.value=await api(`/api/tasks/${detail.value.id}`)}catch(e){error.value=e.message}finally{loading=false}}
async function action(job,verb){if(verb==='cancel'&&!await confirmAction(`取消任务 #${job.id}？`,{title:'取消任务',danger:true}))return;busy.value=true;error.value='';try{await api(`/api/tasks/${job.id}/${verb}`,{method:'POST'});success.value=verb==='retry'?'任务已重新排队':'取消请求已提交';await load()}catch(e){error.value=e.message}finally{busy.value=false}}
async function reindex(){if(busy.value)return;busy.value=true;error.value='';try{const result=await api('/api/tasks/reindex',{method:'POST',body:JSON.stringify({document_id:documentId.value})});success.value=`重新切分任务 #${result.job_id} 已排队，完成后建立新文档版本`;await load()}catch(e){error.value=e.message}finally{busy.value=false}}
onMounted(async()=>{await load();if(can('kb.read')&&can('kb.write'))try{docs.value=await api('/api/documents')}catch{}timer=setInterval(()=>{if(auto.value)load()},3000)})
onUnmounted(()=>clearInterval(timer))
</script>
<template><div class="page-stack"><div class="page-intro"><div><h2>运行状态</h2><p>真实持久任务、存储用量与模型调用记录</p></div><div class="toolbar"><label><input v-model="auto" type="checkbox"/>每 3 秒刷新</label><button class="secondary-button" @click="load">立即刷新</button></div></div><div v-if="error" class="error-banner">{{error}}</div><div v-if="success" class="success-banner">{{success}}</div><template v-if="state"><div class="stat-grid"><div class="stat-card"><div><span>{{state.queue.mode==='external'?'独立工作进程':'内嵌工作进程'}}</span><strong>{{state.queue.worker_alive?'运行中':'未运行'}}</strong><small>并发 {{state.queue.concurrency}} · 心跳 {{state.queue.heartbeat_age_seconds??'—'}} 秒前</small></div></div><div class="stat-card"><div><span>排队 / 执行</span><strong>{{state.queue.counts.queued||0}} / {{state.queue.counts.running||0}}</strong></div></div><div class="stat-card"><div><span>失败 / 中断</span><strong>{{state.queue.counts.failed||0}} / {{state.queue.counts.interrupted||0}}</strong></div></div><div class="stat-card"><div><span>磁盘可用</span><strong>{{bytes(state.storage.disk_free_bytes)}}</strong><small>数据库：{{state.database_backend==='postgresql'?'PostgreSQL':'SQLite'}}</small></div></div></div><div class="grid-2"><section class="card metrics"><h3>存储</h3><p>原文件存储：{{state.storage.original_backend==='s3'?'对象存储':'本地目录'}} · 对象引用 {{state.storage.object_references||0}} 个<br/>本地文件 {{state.storage.upload_files}} 个 · {{bytes(state.storage.uploads_bytes)}}</p><p>数据库 {{state.database_backend==='postgresql'?'PostgreSQL 服务':bytes(state.storage.database_bytes)}} · {{state.storage.documents}} 个文档版本 · {{state.storage.chunks}} 个片段</p><p>缺失原文件：{{state.storage.missing_originals}}（历史演示的空路径不计入）</p><p>检查时间：{{new Date(state.checked_at).toLocaleString()}}</p></section><section class="card metrics"><h3>模型调用</h3><p>总计 {{state.model_calls.total}} · 成功 {{state.model_calls.succeeded||0}} · 失败 {{state.model_calls.failed||0}} · 正在调用 {{state.model_calls.running||0}}</p><p>成功调用平均耗时：{{state.model_calls.average_latency_ms??'暂无'}} ms</p><p>已报告输入 / 输出 Token：{{state.model_calls.input_tokens??'服务未返回'}} / {{state.model_calls.output_tokens??'服务未返回'}}</p><p>无返回用量时不估算成本。服务探测仅在配置页点击后执行。</p></section></div><details v-if="can('kb.write')" class="card metrics reindex-panel"><summary>高级操作：重新切分文档</summary><form @submit.prevent="reindex"><h3>重新切分已有文档</h3><p>采用本次提交时的切分参数，保留旧版本和旧引用。</p><div class="toolbar"><select v-model="documentId" class="select document-select" required><option value="">选择文档版本</option><option v-for="doc in docs" :key="doc.id" :value="doc.id">#{{doc.id}} {{doc.name}} {{doc.version}}</option></select><button class="primary-button" :disabled="!documentId||busy">提交重新切分任务</button></div></form></details><section class="card"><div class="card-header"><div><h3>任务队列 · {{total}} 条</h3><p>排队任务可取消；失败、中断或取消的任务可按上限手动重试</p></div><div class="toolbar"><select v-model="status" class="select narrow" @change="page=1;load()"><option value="">全部状态</option><option v-for="(name,key) in states" :key="key" :value="key">{{name}}</option></select><select v-model="kind" class="select narrow" @change="page=1;load()"><option value="">全部类型</option><option v-for="(name,key) in kinds" :key="key" :value="key">{{name}}</option></select></div></div><div class="card-body table-wrap"><table><thead><tr><th>ID / 类型</th><th>状态 / 进度</th><th>尝试次数</th><th>提交 / 完成时间</th><th>错误</th><th>操作</th></tr></thead><tbody><tr v-for="job in tasks" :key="job.id"><td>#{{job.id}} {{kinds[job.kind]}}</td><td><span class="badge" :class="job.status==='failed'?'red':job.status==='completed'?'green':'amber'">{{states[job.status]}}</span> {{job.progress}}%</td><td>{{job.attempts}} / {{job.max_attempts}}</td><td>{{new Date(job.created_at).toLocaleString()}}<br/><small>{{job.finished_at?new Date(job.finished_at).toLocaleString():'—'}}</small></td><td class="task-error">{{job.error||'—'}}</td><td><div class="toolbar"><button class="secondary-button" @click="detail=job">查看结果</button><button v-if="can('ops.manage')&&['failed','interrupted','cancelled'].includes(job.status)" class="secondary-button" :disabled="busy||job.attempts>=job.max_attempts" @click="action(job,'retry')">重试</button><button v-if="can('ops.manage')&&['queued','running'].includes(job.status)" class="danger-button" :disabled="busy" @click="action(job,'cancel')">取消</button></div></td></tr></tbody></table><p v-if="!tasks.length" class="empty">此筛选条件下没有任务</p></div><div class="pagination"><button class="secondary-button" :disabled="page<=1" @click="page--;load()">上一页</button><span>{{page}} / {{Math.max(1,Math.ceil(total/20))}}</span><button class="secondary-button" :disabled="page*20>=total" @click="page++;load()">下一页</button></div></section><section class="card"><div class="card-header"><h3>最近模型调用</h3></div><div class="card-body table-wrap"><table><thead><tr><th>ID / 类型</th><th>模型</th><th>任务 / 用户</th><th>状态</th><th>耗时 / HTTP</th><th>错误</th></tr></thead><tbody><tr v-for="call in state.recent_calls" :key="call.id"><td>#{{call.id}} {{call.kind}}</td><td>{{call.model}}</td><td>{{call.job_id||'—'}} / {{call.user_id||'—'}}</td><td>{{({succeeded:'成功',failed:'失败',running:'调用中',interrupted:'已中断'})[call.status]||call.status}}</td><td>{{call.latency_ms??'—'}} ms / {{call.status_code||'—'}}</td><td>{{call.error||'—'}}</td></tr></tbody></table><div v-if="!state.recent_calls.length" class="empty">尚无新版模型调用记录</div></div></section></template><ADrawer :open="!!detail" :width="'min(720px,100vw)'" :title="'任务 #'+(detail?.id||'')+' · '+(states[detail?.status]||'')" @close="detail=null"><div v-if="detail" class="task-detail"><div v-if="detail.error" class="error-banner">{{detail.error}}</div><router-link v-if="detail.result.report_id" :to="{path:'/reports',query:{task:detail.result.report_id}}" class="primary-button">打开报告正文</router-link><router-link v-if="detail.result.blueprint" :to="{path:'/reports',query:{designJob:detail.id}}" class="primary-button">预览并保存生成的模板</router-link><router-link v-if="detail.result.document_id" :to="`/documents/${detail.result.document_id}`" class="primary-button">查看重新切分版本</router-link><pre>{{JSON.stringify(detail.result,null,2)}}</pre></div></ADrawer></div></template>
<style scoped>.metrics{padding:22px}.metrics h3{margin-top:0}.metrics p{font-size:13px;color:#617789;line-height:1.7}.stat-card small{font-size:11px;color:#617789}.narrow{width:150px}.document-select{max-width:650px;width:auto;flex:1}.pagination{padding:0 22px 22px;display:flex;gap:15px;align-items:center;justify-content:flex-end;font-size:13px}.task-error{max-width:260px;color:#a12935;font-size:12px}.task-detail{max-width:100%}.reindex-panel summary{cursor:pointer;font-size:14px;font-weight:500}.table-wrap table{min-width:800px}.task-detail pre{white-space:pre-wrap;overflow-wrap:anywhere;font-size:12px}td{font-size:12px}</style>
